SELECT "nct", "author", "year", "pubmed_id", "follow_up_duration_rx_months" AS "Experimental Arm", "follow_up_duration_control_months" AS "Control Arm" FROM public."clinical_trials" WHERE "cancer_type" ILIKE '%Head and Neck%' AND "follow_up_duration_rx_months" IS NOT NULL AND "follow_up_duration_control_months" IS NOT NULL